% Misfit of the true parameters against the high-resolution data (step 0.3 in
% notes/high_res_plan.md). The true a is sampled on the m_p parameter grid and the forward problem
% is solved on the inversion grid m, so the misfit is the floor that an inversion can reach.
% Requires mat/fractal_fault_m<data_m>_mp<data_m>/receiverData.mat, generated by
% fractal_fault_generate_data.m (data_m = 1001 by default). Grid sizes can be set before running
% the script, e.g. matlab -batch "data_m=251; mList=[76 151]; high_res_misfit_floor"
addSubpaths;
if ~exist('mList', 'var')
    mList = [76, 151, 251];
end
if ~exist('m_p', 'var')
    m_p = 26;
end
if ~exist('data_m', 'var')
    data_m = 1001;
end
order = 8;
loadDataPath = sprintf('mat/fractal_fault_m%d_mp%d/receiverData.mat', data_m, data_m);
S = load(loadDataPath);

misfitFloor = zeros(size(mList));
for i = 1:numel(mList)
    parSetOpts = struct('m', mList(i), 'm_p', m_p, 'misfitType', 'velocity', 'receiverSpacing', 2, ...
                        'inversionParameters', {{'a'}}, 'initialGuessValues', 0.0135);
    [~, trueParset] = pars.rsFriction2DFractalFaultInversion(parSetOpts);
    optObj = AntiplaneShear2DRSFrictionOpt(trueParset, {'a'}, order);

    nr = numel(trueParset.receivers.x);
    receiverRecordings = cell(nr, 1);
    for r = 1:nr
        j = find(cellfun(@(x) isequal(x, trueParset.receivers.x{r}), S.receiverData.positions), 1);
        receiverRecordings{r} = S.receiverData.recordings{j};
    end
    optObj.receiverData = receiverRecordings;

    optObj.runForward(false);
    misfitFloor(i) = optObj.computeMisfit();
    fprintf('m = %d, m_p = %d: misfit of the true a = %.4g\n', mList(i), m_p, misfitFloor(i));
end
save(sprintf('mat/inversion/high_res_misfit_floor_data%d_mp%d.mat', data_m, m_p), 'mList', 'm_p', 'data_m', 'misfitFloor');
